  state.shake=Math.max(0,state.shake-dt);if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)ui.toast.classList.add('hidden');}
  if(Math.random()<dt*.12)state.combo=0;
  updateHud();
}

  // wrist cuff highlight
